import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '../lib/db';

// Define the shape of a product
interface Product {
  id: number;
  name: string;
  price: number;
}

// Create a cached version of the data fetching function
const getCachedProducts = unstable_cache(
  async () => {
    // In a real app, this would be a DB call
    const products = await getAllProducts();
    return products as Product[];
  },
  ['products-list'], // Cache key parts
  { tags: ['products'] } // Tags for revalidation
);

export default async function Page() {
  const products = await getCachedProducts();
  const generatedAt = new Date().toISOString();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main>
      <h1>Product Catalog</h1>
      <p>Last updated: {generatedAt}</p>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </main>
  );
}
